using System;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using KGV.Core.Interfaces;using KGV.Core.Models;
namespace KGV.Core.Utilities;
public static class SerienbriefArchivService{public static async Task<IReadOnlyList<SerienbriefArchivResult>> ArchiveAsync(IEnumerable<SerienbriefPdfResult> pdfs,ISupabaseService service,CancellationToken cancellationToken=default){var result=new List<SerienbriefArchivResult>();var seen=new HashSet<string>(StringComparer.Ordinal);foreach(var pdf in pdfs){if(!seen.Add(pdf.RowKey))continue;if(pdf.PdfBytes is null||pdf.PdfBytes.Length==0){result.Add(new(pdf.RowKey,pdf.MitgliedId,pdf.ParzelleId,null,pdf.Dateiname,pdf.Fehler??"PDF fehlt."));continue;}if(pdf.MitgliedId<=0){result.Add(new(pdf.RowKey,pdf.MitgliedId,pdf.ParzelleId,null,pdf.Dateiname,"Mitglied fehlt."));continue;}try{var upload=await service.CreateDokumentAsync(new DokumentUploadRequest{MitgliedId=(int)pdf.MitgliedId,ParzelleId=pdf.ParzelleId is >0?(int)pdf.ParzelleId:null,Titel="Serienbrief",FileName=pdf.Dateiname,MimeType="application/pdf",FileContent=pdf.PdfBytes});result.Add(new(pdf.RowKey,pdf.MitgliedId,pdf.ParzelleId,upload.Document?.Id,pdf.Dateiname,upload.Success?null:upload.Message));}catch(Exception ex){result.Add(new(pdf.RowKey,pdf.MitgliedId,pdf.ParzelleId,null,pdf.Dateiname,ex.Message));}}return result;}}
